import{_ as t,o as a,c as n,a3 as r}from"./chunks/framework.CpLciM8b.js";const u=JSON.parse('{"title":"Health badges","description":"","frontmatter":{},"headers":[],"relativePath":"guide/badges.md","filePath":"guide/badges.md","lastUpdated":1785923002000}'),s={name:"guide/badges.md"};function o(i,e,d,h,l,c){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="health-badges" tabindex="-1">Health badges <a class="header-anchor" href="#health-badges" aria-label="Permalink to &quot;Health badges&quot;">​</a></h1><p>A README badge is how a repository advertises what it can be trusted with. Flakemetry holds a richer signal than a passing build — turn it on under <strong>Settings → Badges</strong> and copy the snippet.</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">![flaky health](http://your-flakemetry/badge/bdg_xxx/health.svg)</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">http://your-flakemetry/projects/…/flaky</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h2 id="the-four-variants" tabindex="-1">The four variants <a class="header-anchor" href="#the-four-variants" aria-label="Permalink to &quot;The four variants&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variant</th><th>Shows</th></tr></thead><tbody><tr><td><code>health</code></td><td>Share of tests not currently flagged flaky</td></tr><tr><td><code>flakes</code></td><td>Flaky occurrences in the last 7 days</td></tr><tr><td><code>quarantined</code></td><td>Tests currently quarantined</td></tr><tr><td><code>worst</code></td><td>The highest flaky score in the project</td></tr></tbody></table><p>Each is available as <code>.svg</code> for embedding and <code>.json</code> in the <a href="https://shields.io/badges/endpoint-badge" target="_blank" rel="noreferrer">Shields endpoint schema</a> if you would rather render it yourself.</p><p>An empty project reads <strong>no data</strong>, in grey. A green badge earned by having ingested nothing would be the most misleading thing this endpoint could produce.</p><h2 id="about-the-token-in-the-url" tabindex="-1">About the token in the URL <a class="header-anchor" href="#about-the-token-in-the-url" aria-label="Permalink to &quot;About the token in the URL&quot;">​</a></h2><p>GitHub&#39;s image proxy fetches a README image with no headers, so whatever authorises a badge has to sit in the URL.</p><p>That is why badges use their <strong>own</strong> token rather than an ingest token. An ingest token grants write; this one grants four aggregate numbers and nothing else. Never put an ingest token in a README.</p><p>The badge token is stored in the clear and shown every time the settings page is opened, because it is a capability meant to be published, not a secret. Treat it accordingly:</p><ul><li><strong>Rotate</strong> issues a new token. Every badge already embedded anywhere stops working and has to be updated — that is what makes it revocable.</li><li><strong>Turn off</strong> removes it entirely, and every badge URL starts rendering <em>unknown</em>.</li></ul><h2 id="why-it-never-returns-an-error" tabindex="-1">Why it never returns an error <a class="header-anchor" href="#why-it-never-returns-an-error" aria-label="Permalink to &quot;Why it never returns an error&quot;">​</a></h2><p>A 404 or a 500 on a badge is a broken image for every reader of the page it sits in. An unknown token, a variant that does not exist, and a database having a bad moment all render the same grey <strong>unknown</strong> pill with a <code>200</code>.</p><h2 id="load" tabindex="-1">Load <a class="header-anchor" href="#load" aria-label="Permalink to &quot;Load&quot;">​</a></h2><p>Responses carry <code>Cache-Control: public, max-age=300</code> and an <code>ETag</code>, and the metrics come from counts and a rollup aggregate rather than raw executions — so a README on a busy repository cannot put pressure on the queries the dashboard depends on. Requests are also rate-limited per badge token.</p><h2 id="public-instances" tabindex="-1">Public instances <a class="header-anchor" href="#public-instances" aria-label="Permalink to &quot;Public instances&quot;">​</a></h2><p>Set <code>FLAKEMETRY_PUBLIC_API_URL</code> to the address a reader of your README would use. It defaults to <code>http://localhost:4000</code>, which is right for a local stack and wrong for anything a colleague opens.</p>',18)])])}const p=t(s,[["render",o]]);export{u as __pageData,p as default};
